INSERT INTO `v1_7903e37db32afc6109a128c856d3c894b7058be2440d184470a193b368c13fb2` VALUES (101, 1, "剛力なる鳥像", 0, "ガーゴイル", 1, 0, "高い物理攻撃力を宿し、強力な範囲攻撃を行うよう\nプログラムされたボスが現れる。");
